    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker for a trading pair
        :param str symbol: unified market symbol
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.base_network]: base currency network when symbol is ambiguous
        :param str [params.quote_network]: quote currency network when symbol is ambiguous
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        market = self.coinrabbit_resolve_market(symbol, params)
        marketInfo = self.safe_dict(market, 'info', {})
        request = {
            'symbol': self.safe_string(marketInfo, 'symbol', market['symbol']),
            'base_network': self.safe_string_2(params, 'base_network', 'baseNetwork', self.safe_string(marketInfo, 'base_network')),
            'quote_network': self.safe_string_2(params, 'quote_network', 'quoteNetwork', self.safe_string(marketInfo, 'quote_network')),
        }
        params = self.omit(params, ['base_network', 'baseNetwork', 'quote_network', 'quoteNetwork'])
        response = await self.publicGetMarketTicker(self.extend(request, params))
        tickerPayload = self.coinrabbit_unwrap_response(response)
        return self.parse_ticker(tickerPayload, market)

