    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string(order, 'id')
        apiSymbol = self.safe_string(order, 'symbol')
        symbol = self.safe_symbol(apiSymbol, market)
        if symbol is None and apiSymbol is not None:
            symbol = apiSymbol
        timestamp = self.parse8601(self.safe_string(order, 'created_at'))
        status = self.parse_order_status(self.safe_string_upper(order, 'status'))
        side = self.safe_string_lower(order, 'side')
        type = self.safe_string_lower(order, 'type')
        price = self.safe_string(order, 'price')
        amount = self.safe_string(order, 'amount')
        cost = self.safe_string(order, 'quote_amount')
        clientOrderId = self.safe_string(order, 'client_order_id')
        return self.safe_order({
            'info': order,
            'id': id,
            'clientOrderId': clientOrderId,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': None,
            'status': status,
            'symbol': symbol,
            'type': type,
            'timeInForce': None,
            'postOnly': None,
            'side': side,
            'price': price,
            'stopPrice': None,
            'triggerPrice': None,
            'amount': amount,
            'cost': cost,
            'average': None,
            'filled': None,
            'remaining': None,
            'fee': None,
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers: dict = None, body: Str = None):
        query = self.omit(params, self.extract_params(path))
        signedPath = '/' + self.version + '/' + self.implode_params(path, params)
        if (method == 'GET') or (method == 'DELETE'):
            if query:
                signedPath += '?' + self.urlencode(query)
        url = self.urls['api']['rest'] + signedPath
        if api == 'private':
            self.check_required_credentials()
            headers = headers if (headers is not None) else {}
            timestamp = str(self.milliseconds())
            rawBody = ''
            if method == 'POST':
                headers = {
                    'Content-Type': 'application/json',
                }
                if query:
                    rawBody = self.json(query)
                    body = rawBody
            payload = method + '\n' + signedPath + '\n' + rawBody + '\n' + timestamp
            signature = self.hmac(self.encode(payload), self.encode(self.secret), hashlib.sha256, 'hex')
            headers = self.extend({
                'X-API-KEY': self.apiKey,
                'X-TIMESTAMP': timestamp,
                'X-SIGNATURE': signature,
            }, headers)
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if response is None:
            return None
        errorMessage = self.safe_string(response, 'error')
        if errorMessage is not None:
            feedback = self.id + ' ' + body
            if httpCode == 401 or httpCode == 403:
                raise AuthenticationError(feedback)
            if httpCode == 404:
                raise OrderNotFound(feedback)
            if httpCode == 400:
                if body.find('INSUFFICIENT_BALANCE') >= 0:
                    raise InsufficientFunds(feedback)
                raise BadRequest(feedback)
            if httpCode == 409:
                raise InvalidOrder(feedback)
            raise ExchangeError(feedback)
        envelopeResult = self.safe_bool(response, 'result', None)
        if envelopeResult is not None and not envelopeResult:
            raise ExchangeError(self.id + ' ' + body)
        if httpCode == 401 or httpCode == 403:
            raise AuthenticationError(self.id + ' ' + body)
        if httpCode == 404 and url.find('/trading/order/') >= 0:
            raise OrderNotFound(self.id + ' order not found')
        return None
